window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bd8e6397a7ee76eb"]={"versions": [{"id": "FIG-bd8e6397a7ee76eb", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECUC-Parameterschnittstellenmodells (ECU Configuration Parameter Definition) für das BSW-Modul Diagnostic Event Manager (Dem) innerhalb der AUTOSAR Classic Platform. Das Diagramm spezifiziert die Metamodell-Struktur des Konfigurationscontainers <code>DemDTCAttributes</code> (Teil II) bezüglich Alterung, Priorisierung, Speicherzielen und Freeze-Frame-Klassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentraler Konfigurationscontainer ist <code>DemDTCAttributes</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..65535). Enthaltene Parameter und Referenzen:</p>\n<ul class=\"fig-list\"><li><code>DemAgingAllowed</code>: <code>EcucBooleanParamDef</code> (über Komposition <code>+parameter</code>).\n</li><li><code>DemDTCPriority</code>: <code>EcucIntegerParamDef</code> mit Wertebereich <code>min = 0</code>, <code>max = 255</code> (über Komposition <code>+parameter</code>).\n</li><li><code>DemAgingCycleRef</code>: <code>EcucReferenceDef</code>, Multiplizität 0..1 (über Komposition <code>+reference</code>).\n</li><li><code>DemDTCSignificance</code>: <code>EcucEnumerationParamDef</code>, Multiplizität 0..1 (über Komposition <code>+parameter</code>), aggregiert über <code>+literal</code> die Werte <code>DEM_EVENT_SIGNIFICANCE_FAULT</code> und <code>DEM_EVENT_SIGNIFICANCE_OCCURRENCE</code> (<code>EcucEnumerationLiteralDef</code>).\n</li><li><code>DemMemoryDestinationRef</code>: <code>EcucChoiceReferenceDef</code>, Multiplizität 1..2 (über Komposition <code>+parameter</code>), referenziert über Assoziationen <code>+destination</code>:\n<ul class=\"fig-list\"><li><code>DemUserDefinedMemory</code>: <code>EcucParamConfContainerDef</code>, Multiplizität 0..30.\n</li><li><code>DemPrimaryMemory</code>: <code>EcucParamConfContainerDef</code>, Multiplizität 1..1.\n</li><li><code>DemMirrorMemory</code>: <code>EcucParamConfContainerDef</code>, Multiplizität 0..1.\n</li></ul>\n</li><li><code>DemJ1939FreezeFrameClassRef</code>: <code>EcucReferenceDef</code>, Multiplizität 0..1 (über Komposition <code>+reference</code>), referenziert über <code>+destination</code> den Container <code>DemJ1939FreezeFrameClass</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..255).\n</li><li><code>DemJ1939ExpandedFreezeFrameClassRef</code>: <code>EcucReferenceDef</code>, Multiplizität 0..1 (über Komposition <code>+reference</code>), referenziert über <code>+destination</code> ebenfalls <code>DemJ1939FreezeFrameClass</code>.\n</li><li><code>DemWWHOBDFreezeFrameClassRef</code>: <code>EcucReferenceDef</code>, Multiplizität 0..1 (über Komposition <code>+reference</code>), referenziert über <code>+destination</code> den Container <code>DemFreezeFrameClass</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..65535).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Ablauf- oder Sequenzdarstellung. Die Relationen definieren Entwurfszeit- und Generierungszeitstrukturen für die Parametrierung des Dem-Fehlerspeichers und der Freeze-Frame-Zuordnungen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Definition der ECUC-Parameterstruktur für <code>DemDTCAttributes</code>. Mindestens ein und maximal zwei Speicherziele (<code>DemMemoryDestinationRef</code>) müssen konfiguriert werden, wobei <code>DemPrimaryMemory</code> zwingend vorhanden sein muss. Alterungsreferenzen (<code>DemAgingCycleRef</code>) und DTC-Signifikanz (<code>DemDTCSignificance</code>) sind optional (0..1). Spezifische Freeze-Frame-Klassen für J1939 und WWH-OBD werden über optionale Referenzen angebunden.</p>"}, {"id": "FIG-7a1b14225cdb3361", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECUC-Parameterschnittstellenmodells (ECU Configuration Parameter Definition) für das BSW-Modul Diagnostic Event Manager (Dem) innerhalb der AUTOSAR Classic Platform. Das Diagramm spezifiziert die Metamodell-Struktur des Konfigurationscontainers <code>DemDTCAttributes</code> (Teil II) bezüglich Alterung, Priorisierung, Speicherzielen und Freeze-Frame-Klassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentraler Konfigurationscontainer ist <code>DemDTCAttributes</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..65535). Enthaltene Parameter und Referenzen:</p>\n<ul class=\"fig-list\"><li><code>DemAgingAllowed</code>: <code>EcucBooleanParamDef</code> mit <code>defaultValue = false</code> (über Komposition <code>+parameter</code>).\n</li><li><code>DemDTCPriority</code>: <code>EcucIntegerParamDef</code> mit Wertebereich <code>min = 0</code>, <code>max = 255</code> (über Komposition <code>+parameter</code>).\n</li><li><code>DemAgingCycleRef</code>: <code>EcucReferenceDef</code>, Multiplizität 0..1 (über Komposition <code>+reference</code>).\n</li><li><code>DemDTCSignificance</code>: <code>EcucEnumerationParamDef</code>, Multiplizität 0..1 (über Komposition <code>+parameter</code>), aggregiert über <code>+literal</code> die Werte <code>DEM_EVENT_SIGNIFICANCE_FAULT</code> und <code>DEM_EVENT_SIGNIFICANCE_OCCURRENCE</code> (<code>EcucEnumerationLiteralDef</code>).\n</li><li><code>DemMemoryDestinationRef</code>: <code>EcucChoiceReferenceDef</code>, Multiplizität 1..2 (über Komposition <code>+parameter</code>), referenziert über Assoziationen <code>+destination</code>:\n<ul class=\"fig-list\"><li><code>DemUserDefinedMemory</code>: <code>EcucParamConfContainerDef</code>, Multiplizität 0..30.\n</li><li><code>DemPrimaryMemory</code>: <code>EcucParamConfContainerDef</code>, Multiplizität 1..1.\n</li><li><code>DemMirrorMemory</code>: <code>EcucParamConfContainerDef</code>, Multiplizität 0..1.\n</li></ul>\n</li><li><code>DemJ1939FreezeFrameClassRef</code>: <code>EcucReferenceDef</code>, Multiplizität 0..1 (über Komposition <code>+reference</code>), referenziert über <code>+destination</code> den Container <code>DemJ1939FreezeFrameClass</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..255).\n</li><li><code>DemJ1939ExpandedFreezeFrameClassRef</code>: <code>EcucReferenceDef</code>, Multiplizität 0..1 (über Komposition <code>+reference</code>), referenziert über <code>+destination</code> ebenfalls <code>DemJ1939FreezeFrameClass</code>.\n</li><li><code>DemWWHOBDFreezeFrameClassRef</code>: <code>EcucReferenceDef</code>, Multiplizität 0..1 (über Komposition <code>+reference</code>), referenziert über <code>+destination</code> den Container <code>DemFreezeFrameClass</code> (<code>EcucParamConfContainerDef</code>, Multiplizität 0..65535).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Ablauf- oder Sequenzdarstellung. Die Relationen definieren Entwurfszeit- und Generierungszeitstrukturen für die Parametrierung des Dem-Fehlerspeichers und der Freeze-Frame-Zuordnungen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Definition der ECUC-Parameterstruktur für <code>DemDTCAttributes</code>. <code>DemAgingAllowed</code> besitzt standardmäßig den Defaultwert <code>false</code>. Mindestens ein und maximal zwei Speicherziele (<code>DemMemoryDestinationRef</code>) müssen konfiguriert werden, wobei <code>DemPrimaryMemory</code> zwingend vorhanden sein muss. Alterungsreferenzen (<code>DemAgingCycleRef</code>) und DTC-Signifikanz (<code>DemDTCSignificance</code>) sind optional (0..1). Spezifische Freeze-Frame-Klassen für J1939 und WWH-OBD werden über optionale Referenzen angebunden.</p>"}], "trans": [{"from": "FIG-bd8e6397a7ee76eb", "to": "FIG-7a1b14225cdb3361", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>DemAgingAllowed (<code>EcucBooleanParamDef</code>): Parameterattribut <code>defaultValue = false</code> hinzugefügt.\n</li></ul>"}]};
